def load_and_verify_image(file_path):
    """Load and verify an image, return None if invalid"""
    try:

        img = tf.io.read_file(file_path)

        img = tf.image.decode_image(img, channels=3, expand_animations=False)

        img.set_shape([img_height, img_width, 3])
        return img
    except:
        return None


def get_valid_files(directory):
    """Get list of valid image files in directory"""
    valid_files = []
    for class_name in os.listdir(directory):
        class_path = os.path.join(directory, class_name)
        if os.path.isdir(class_path):
            for filename in os.listdir(class_path):
                file_path = os.path.join(class_path, filename)

                try:
                    img = tf.io.read_file(file_path)

                    decoded = tf.image.decode_image(img, channels=3, expand_animations=False)

                    file_size = os.path.getsize(file_path)
                    if file_size > 1000:
                        valid_files.append((file_path, class_name))
                except:
                    pass
    return valid_files


valid_train_files = get_valid_files('data_small')
print(f"Found {len(valid_train_files)} valid training files")

if len(valid_train_files) == 0:
    print("WARNING: No valid image files found in the dataset!")
    print("All files appear to be Git LFS placeholder files.")


    train_ds = tf.data.Dataset.from_tensor_slices((
        tf.random.uniform((1, img_height, img_width, 3)),
        tf.constant([[1.0]])
    )).batch(1)
else:

    file_paths = [f[0] for f in valid_train_files]
    class_names = [f[1] for f in valid_train_files]


    label_map = {'Chic': 0, 'Duck': 1}
    labels = [label_map[name] for name in class_names]


    file_paths_ds = tf.data.Dataset.from_tensor_slices(file_paths)
    labels_ds = tf.data.Dataset.from_tensor_slices(labels)


    def load_image(path, label):
        img = tf.io.read_file(path)
        img = tf.image.decode_image(img, channels=3)
        img = tf.image.resize(img, [img_height, img_width])
        img = tf.cast(img, tf.float32) / 255.0
        return img, tf.cast(label, tf.float32)

    dataset = tf.data.Dataset.zip((file_paths_ds, labels_ds))
    train_ds = dataset.map(load_image).batch(batch_size)


    train_size = int(0.8 * len(valid_train_files))
    train_ds = train_ds.take(train_size)

